// IdGenerator port. IDs are generated by the application and stored as text, never by the database.
//
// Semantics: `next()` returns a non-empty string, unique within a process. It never fails.
// Callers must not parse an ID or rely on its order.
//
// Adapters: uuid (crypto.randomUUID), sequence (predictable, for tests).

export interface IdGenerator {
  next(): string;
}
